INSERT INTO [dbo].[BalanceNegative] (
                    [ExecDate]
                    ,[MatchID]
                    ,[ActionID]
                    ,[GroupID]
                    ,[CustID]
                    ,[Balance]
                    ,[StatusID]
                    ,[Remark]
                )
SELECT 
		GETDATE() AS ExecDate
		,91202628 MatchId
		,182 ActionId -- UNDO
		,1 AS GroupID
        ,b.CustID
		,sum(w - bef_w + (pc - (playerdiscount * stake))) _bal
		,0 as StatusId
		,NULL Remark
FROM OPENJSON(@json)
	WITH (
	t   BIGINT
	,w  MONEY
	,pc  MONEY
	,bef_w money
	
) temp
inner join dbo.bettrans b with(nolock) 
	on temp.t = b.transid
group by custid 
having sum(w - bef_w + (pc - (playerdiscount * stake))) < 0